51	/**
52	 * @author Vitaliy Fedoriv
53	 */
54	
55	@RestController
56	@CrossOrigin(exposedHeaders = "errors, content-type")
57	@RequestMapping("/api")
58	public class OwnerRestControllerV1 implements OwnersApi {
59	
60	    private final ClinicService clinicService;
61	
62	    private final OwnerMapper ownerMapper;
63	
64	    private final PetMapper petMapper;
65	
66	    private final VisitMapper visitMapper;
67	
68	    public OwnerRestControllerV1(ClinicService clinicService,
69	                                 OwnerMapper ownerMapper,
70	                                 PetMapper petMapper,
71	                                 VisitMapper visitMapper) {
72	        this.clinicService = clinicService;
73	        this.ownerMapper = ownerMapper;
74	        this.petMapper = petMapper;
75	        this.visitMapper = visitMapper;
76	    }
77	
78	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
79	    @Override
80	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
81	        Collection<Owner> owners;
82	        if (lastName != null) {
83	            owners = this.clinicService.findOwnerByLastName(lastName);
84	        } else {
85	            owners = this.clinicService.findAllOwners();
86	        }
87	        if (owners.isEmpty()) {
88	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
89	        }
90	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
91	    }
92	
93	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
94	    @Override
95	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
96	        Owner owner = this.clinicService.findOwnerById(ownerId);
97	        if (owner == null) {
98	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
99	        }
100	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
106	        HttpHeaders headers = new HttpHeaders();
107	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
108	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
109	            rejectDuplicateHousehold(owner.getLastName(), owner.getAddress());
110	        }
111	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
112	        rejectDuplicateTelephone(telephone);
113	        owner.setTelephone(telephone);
114	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
115	        if (owner.getRegistrationDate() == null) {
116	            owner.setRegistrationDate(java.time.LocalDate.now());
117	        }
118	        owner.setCustomerCode(assignCustomerCode(owner.getLastName()));
119	        this.clinicService.saveOwner(owner);
120	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
121	        headers.setLocation(UriComponentsBuilder.newInstance()
122	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
123	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
124	    }
125	
126	    /**
127	     * Assigns an owner's {@code customerCode} on create, formatted {@code '<LAST3>-<NNNN>'} where
128	     * LAST3 is the upper-cased first three letters of the last name and NNNN is a global 4-digit
129	     * zero-padded sequence equal to one more than the current number of owners (e.g. {@code 'SMI-0007'}).
130	     *
131	     * @param lastName the owner's last name
132	     * @return the assigned customer code
133	     */
134	    private String assignCustomerCode(String lastName) {
135	        String name = lastName == null ? "" : lastName;
136	        String last3 = name.substring(0, Math.min(3, name.length()))
137	            .toUpperCase(java.util.Locale.ROOT);
138	        int sequence = this.clinicService.findAllOwners().size() + 1;
139	        return String.format("%s-%04d", last3, sequence);
140	    }
141	
142	    /**
143	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
144	     * stripped. A leading '+' and its country code are kept as given; otherwise country code '+61' is
145	     * assumed and a single leading '0' is dropped from the national digits. The resulting number must
146	     * have 8 to 15 digits after the '+'. For example {@code "0412 345 678"} becomes
147	     * {@code "+61412345678"}. The E.164 value is stored and returned.
148	     *
149	     * @param telephone the raw telephone as submitted
150	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
151	     * @throws InvalidTelephoneException (400 Bad Request) if the value cannot form a valid E.164 number
152	     */
153	    private String normalizeTelephone(String telephone) {
154	        String raw = telephone == null ? "" : telephone.trim();
155	        boolean hasCountryCode = raw.startsWith("+");
156	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
157	        if (hasCountryCode) {
158	            cleaned = cleaned.substring(1);
159	        }
160	        String digits;
161	        if (hasCountryCode) {
162	            digits = cleaned;
163	        } else {
164	            if (cleaned.startsWith("0")) {
165	                cleaned = cleaned.substring(1);
166	            }
167	            digits = "61" + cleaned;
168	        }
169	        if (!digits.matches("[0-9]{8,15}")) {
170	            throw new InvalidTelephoneException(telephone);
171	        }
172	        return "+" + digits;
173	    }
174	
175	    /**
176	     * Syntactic email pattern: a non-empty local part, an '@', a domain with at least one dot and a
177	     * multi-character top-level label. Deliberately lenient about the exact character set while still
178	     * rejecting values that are clearly not addresses (e.g. missing '@').
179	     */
180	    private static final java.util.regex.Pattern EMAIL_PATTERN =
181	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$");
182	
183	    /**
184	     * Normalizes an owner's email. Email is optional: a {@code null} or blank value is left as
185	     * {@code null} (no email). When present it must be a syntactically valid address; the value is
186	     * lower-cased before being stored and returned.
187	     *
188	     * @param email the raw email as submitted, may be {@code null}
189	     * @return the lower-cased email, or {@code null} when none was supplied
190	     * @throws InvalidEmailException (400 Bad Request) if a non-blank value is not a valid address
191	     */
192	    private String normalizeEmail(String email) {
193	        if (email == null || email.isBlank()) {
194	            return null;
195	        }
196	        String trimmed = email.trim();
197	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
198	            throw new InvalidEmailException(email);
199	        }
200	        return trimmed.toLowerCase(java.util.Locale.ROOT);
201	    }
202	
203	    /**
204	     * Rejects creating an owner whose E.164 telephone is already used by another owner. Telephones of
205	     * existing owners are normalized to E.164 the same way before comparison, so equivalent numbers
206	     * submitted in different formats (e.g. national {@code "0412 345 678"} and international
207	     * {@code "+61 412 345 678"}) are still treated as duplicates.
208	     *
209	     * @param telephone the E.164 telephone of the owner being created
210	     * @throws DuplicateTelephoneException (409 Conflict) if another owner already uses this telephone
211	     */
212	    private void rejectDuplicateTelephone(String telephone) {
213	        boolean duplicate = this.clinicService.findAllOwners().stream()
214	            .map(Owner::getTelephone)
215	            .filter(existing -> existing != null)
216	            .map(this::toE164OrNull)
217	            .filter(existing -> existing != null)
218	            .anyMatch(telephone::equals);
219	        if (duplicate) {
220	            throw new DuplicateTelephoneException(telephone);
221	        }
222	    }
223	
224	    /**
225	     * Normalizes an existing owner's telephone to E.164 for duplicate comparison, returning
226	     * {@code null} instead of throwing when the stored value cannot form a valid E.164 number.
227	     */
228	    private String toE164OrNull(String telephone) {
229	        try {
230	            return normalizeTelephone(telephone);
231	        } catch (InvalidTelephoneException e) {
232	            return null;
233	        }
234	    }
235	
236	    /**
237	     * Rejects creating an owner who shares a household with an existing owner, i.e. another owner
238	     * already has the same last name and the same address. Both fields are compared
239	     * case-insensitively and with runs of whitespace collapsed to a single space (and surrounding
240	     * whitespace trimmed), so values that differ only in letter case or spacing still count as a
241	     * match. This check is skipped when the request sets {@code sharesHousehold} to {@code true}.
242	     *
243	     * @param lastName the last name of the owner being created
244	     * @param address the address of the owner being created
245	     * @throws DuplicateHouseholdException (409 Conflict) if another owner shares this household
246	     */
247	    private void rejectDuplicateHousehold(String lastName, String address) {
248	        String normalizedLastName = normalizeForHousehold(lastName);
249	        String normalizedAddress = normalizeForHousehold(address);
250	        boolean duplicate = this.clinicService.findAllOwners().stream()
251	            .anyMatch(existing ->
252	                normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
253	                    && normalizeForHousehold(existing.getAddress()).equals(normalizedAddress));
254	        if (duplicate) {
255	            throw new DuplicateHouseholdException(lastName, address);
256	        }
257	    }
258	
259	    /**
260	     * Normalizes a value for household-duplicate comparison: {@code null} becomes an empty string,
261	     * surrounding whitespace is trimmed, internal runs of whitespace collapse to a single space and
262	     * the result is lower-cased.
263	     */
264	    private String normalizeForHousehold(String value) {
265	        if (value == null) {
266	            return "";
267	        }
268	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
269	    }
270	
271	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
272	    @Override
273	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
274	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
275	        if (currentOwner == null) {
276	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
277	        }
278	        currentOwner.setAddress(ownerFieldsDto.getAddress());
279	        currentOwner.setCity(ownerFieldsDto.getCity());
280	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
281	        currentOwner.setLastName(ownerFieldsDto.getLastName());
282	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
283	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
284	        this.clinicService.saveOwner(currentOwner);
285	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
286	    }
287	
288	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
289	    @Transactional
290	    @Override
291	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
292	        Owner owner = this.clinicService.findOwnerById(ownerId);
293	        if (owner == null) {
294	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
295	        }
296	        this.clinicService.deleteOwner(owner);
297	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
298	    }
299	
300	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
301	    @Override
302	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
303	        Owner owner = this.clinicService.findOwnerById(ownerId);
304	        if (owner == null) {
305	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
306	        }
307	        HttpHeaders headers = new HttpHeaders();
308	        Pet pet = petMapper.toPet(petFieldsDto);
309	        owner.setId(ownerId);
310	        pet.setOwner(owner);
311	        pet.getType().setName(null);
312	        this.clinicService.savePet(pet);
313	        PetDto petDto = petMapper.toPetDto(pet);
314	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
315	            .buildAndExpand(pet.getId()).toUri());
316	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
317	    }
318	
319	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
320	    @Override
321	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
322	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
323	        if (currentOwner != null) {
324	            Pet currentPet = this.clinicService.findPetById(petId);
325	            if (currentPet != null) {
326	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
327	                currentPet.setName(petFieldsDto.getName());
328	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
329	                this.clinicService.savePet(currentPet);
